import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
process.chdir(fileURLToPath(new URL('../',import.meta.url)));
const constants = JSON.parse(await readFile(new URL('../protocol/constants.json', import.meta.url), 'utf8'));
const errors=JSON.parse(await readFile('protocol/error-codes.json','utf8'));
const reasons=JSON.parse(await readFile('protocol/close-reasons.json','utf8'));
const outputs = {
  'packages/protocol/src/constants.ts': '// Generated by scripts/generate-protocol.mjs. Do not edit.\nexport const C = ' + JSON.stringify(constants, null, 2) + ' as const;\nexport const ERROR_CODES = '+JSON.stringify(errors,null,2)+' as const;\nexport const CLOSE_REASONS = '+JSON.stringify(reasons,null,2)+' as const;\n',
  'cli/internal/constants/generated.go': '// Code generated by scripts/generate-protocol.mjs; DO NOT EDIT.\npackage constants\n\n' + Object.entries(constants).map(([k,v]) => `const ${k} = ${v}`).join('\n') + '\n\n'+errors.map(code=>`const CODE_${code} = "${code}"`).join('\n')+'\n'
};
for (const [path, content] of Object.entries(outputs)) {
  if (process.argv.includes('--check')) {
    if (await readFile(path, 'utf8').catch(() => '') !== content) throw new Error(`Regenerate ${path}`);
  } else {
    await mkdir(path.slice(0, path.lastIndexOf('/')), {recursive:true});
    await writeFile(path, content);
  }
}
